package com.pethop.shelter;
import com.pethop.admin.AdminAuditService; import com.pethop.common.exception.ApiException; import com.pethop.notification.NotificationService; import com.pethop.shelter.dto.ShelterResponse; import com.pethop.shelter.dto.VerificationDecisionRequest; import com.pethop.user.User; import java.time.Instant; import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminShelterService{
 private final ShelterRepository shelters; private final NotificationService notifications; private final AdminAuditService audit;
 public AdminShelterService(ShelterRepository s,NotificationService n,AdminAuditService a){shelters=s;notifications=n;audit=a;}
 @Transactional(readOnly=true) public List<ShelterResponse> pending(){return shelters.findAllByVerificationStatusOrderByCreatedAtAsc(VerificationStatus.PENDING).stream().map(ShelterResponse::from).toList();}
 @Transactional(readOnly=true) public ShelterResponse get(UUID id){return ShelterResponse.from(find(id));}
 @Transactional public ShelterResponse decide(UUID id,User admin,VerificationDecisionRequest request){ShelterProfile s=shelters.findByIdForUpdate(id).orElseThrow(()->ApiException.notFound("Refugio no encontrado.")); if(s.getVerificationStatus()!=VerificationStatus.PENDING&&s.getVerificationStatus()!=VerificationStatus.IN_REVIEW)throw ApiException.conflict("El perfil ya fue procesado."); if(request.decision()==VerificationDecision.REJECT&&(request.reason()==null||request.reason().isBlank()))throw ApiException.badRequest("Debe indicar el motivo del rechazo."); VerificationStatus old=s.getVerificationStatus(), next=request.decision()==VerificationDecision.APPROVE?VerificationStatus.VERIFIED:VerificationStatus.REJECTED; s.setVerificationStatus(next); shelters.save(s); String reason=request.reason()==null?null:request.reason().trim(); audit.record(admin,"SHELTER_VERIFICATION_"+request.decision(),"SHELTER",id,old.name(),next.name(),reason); notifications.create(s.getUser(),"SHELTER_VERIFICATION",request.decision()==VerificationDecision.APPROVE?"Perfil verificado en PetHop":"Verificación rechazada",reason==null?"La decisión ha sido registrada.":reason,"SHELTER",id); return ShelterResponse.from(s);}
 private ShelterProfile find(UUID id){return shelters.findById(id).orElseThrow(()->ApiException.notFound("Refugio no encontrado."));}
}
